    stethoscope:'<path d="M6 3v3m8-3v3M4 4v7a6 6 0 0 0 12 0V4M10 17v1a4 4 0 0 0 8 0v-3"/><circle cx="18" cy="12" r="3"/>',
    scan:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5M8 8l8 8m0-8-8 8M3 12h18"/>',
    pill:'<path d="M20 4a5 5 0 0 1 0 7l-9 9a5 5 0 0 1-7-7l9-9a5 5 0 0 1 7 0ZM8 9l7 7"/>',
